insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-goodcycle-dailybasis', 'DailyBasis by GoodCycle', 'GoodCycle', 'supplement', 'physical', 'The first daily multi powder supplement with two cycle-aligned formulas, Replenish and Balance. Each day, one stick pack mixes into 8 to 10 oz of cold water or a beverage of choice, with a light lemon-citrus flavor on a greens base. Both formulas are built on the same foundation: core vitamins and minerals in bioavailable forms, amino acids, probiotics, herbs and botanicals, and a greens blend.

Replenish is taken from the first day of the period through ovulation (about 14 days). It is formulated around the nutrient needs of the first half of the cycle.

Balance is taken from ovulation through the start of the next period (about 14 days). It is formulated around the nutrient needs of the second half of the cycle.

Quality: OB/GYN formulated, manufactured in a GMP-certified facility, made with GRAS ingredients, and third-party tested. Incoming ingredients are tested for heavy metals, toxins and microorganisms.', '$80 (14 Replenish + 14 Balance stick packs); $64 if you subscribe, per takegoodcycle.com', '/products/goodcycle/daily-basis-cover.webp', 'https://takegoodcycle.com/products/daily-basis', '["irregular","cramps"]'::jsonb, '["supplement","hormone-balance"]'::jsonb, '["takegoodcycle.com"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement. The FDA does not approve dietary supplements before they are sold; GoodCycle says it is made in a GMP-certified facility.","materials":"28 single-serve stick packs per box: 14 Replenish (7 g each) and 14 Balance (6.7 g each). Per the Supplement Facts on GoodCycle''s sell sheet:\n\nReplenish (per stick pack): vitamin A (as palmitate) 80 mcg, vitamin C 123 mg, vitamin D3 37.5 mcg, vitamin E 13.9 mg, vitamin K2 (MK-7) 60 mcg, thiamin 4.3 mg, riboflavin 6.2 mg, niacin 30.8 mg, vitamin B6 (P-5-P) 6.2 mg, folate (5-MTHF) 700 mcg DFE, vitamin B12 (methylcobalamin) 50 mcg, biotin 308 mcg, pantothenic acid 8 mg, calcium (citrate) 160 mg, iron (bisglycinate chelate) 18 mg, iodine 123 mcg, magnesium (bisglycinate chelate) 60 mg, zinc 12 mg, selenium 95 mcg, manganese 2 mg, chromium 123 mcg, molybdenum 62 mcg, CoQ10 31.5 mg; greens blend 2,676 mg (organic barley grass, oat grass juice, wheat grass and alfalfa powders); botanicals and herbs blend 590 mg (organic broccoli powder, green tea leaf extract, lutein esters); amino acid blend 944 mg (N-acetyl L-cysteine, taurine, L-leucine, L-isoleucine, L-valine); probiotic blend 205 mg (L. rhamnosus, L. plantarum, L. reuteri, B. bifidum).\n\nBalance (per stick pack): vitamin A (as palmitate) 80 mcg, vitamin C 303 mg, vitamin D3 37.5 mcg, vitamin E 27.4 mg, vitamin K2 (MK-7) 60 mcg, thiamin 6.1 mg, riboflavin 6.1 mg, niacin 15.2 mg, vitamin B6 (P-5-P) 20 mg, folate (5-MTHF) 700 mcg DFE, vitamin B12 (methylcobalamin) 65 mcg, biotin 152 mcg, pantothenic acid 8 mg, calcium (citrate) 310 mg, iron (bisglycinate chelate) 12.3 mg, iodine 121 mcg, magnesium (bisglycinate chelate) 150 mg, zinc 11 mg, selenium 95 mcg, manganese 2 mg, chromium 60 mcg, molybdenum 61 mcg, CoQ10 15.2 mg; greens blend 909 mg; botanicals and herbs blend 786 mg (quercetin dihydrate, organic broccoli powder, alpha lipoic acid, phosphatidylcholine); amino acid blend 545 mg (N-acetyl L-cysteine, taurine, L-leucine, L-isoleucine, L-valine); probiotic blend 197 mg (L. rhamnosus, L. plantarum, L. reuteri, B. bifidum).\n\nOther ingredients (both): citric acid, natural flavor, monk fruit extract, sunflower lecithin.","allergens":"GoodCycle says DailyBasis is certified gluten-free and its ingredients contain no dairy, gluten, lactose, egg, peanuts or coconut. The greens blend includes wheat grass and barley grass.","recalls":"No recalls are mentioned on takegoodcycle.com; check current FDA recall notices.","sideEffects":"In GoodCycle''s 2024 focus group, many participants noted mild stomach upset in the first few days, which they said resolved quickly; GoodCycle suggests starting with half a serving and taking it with food at first.","opinionAlerts":"Contains iron (18 mg in Replenish, 12.3 mg in Balance). GoodCycle says not to take more than one stick pack a day, and not to take it on top of a prenatal vitamin without a doctor''s direction."}'::jsonb, 'GoodCycle says DailyBasis was formulated by an OB/GYN and functional medicine practitioner, with input from a registered dietitian, a nutritionist and a dermatologist. Its consumer study summary names the formulator as OB/GYN Dr. Christy Evans.

The brand describes Replenish (cycle days 1 to 14) as supporting replenishment after the period, energy, and follicle development, and Balance (days 14 to 28) as supporting mood and focus and easing PMS symptoms and cycle-related inflammation. These are the brand''s descriptions; GoodCycle''s site notes they have not been evaluated by the FDA.

GoodCycle''s own consumer study (2024, run by the brand, not a clinical trial): 45 people across life stages used the Cycle Routine for a full cycle (30+ days each) and reported their own results, with no placebo or comparison group. 98% were in their reproductive years or perimenopause, and participants included regular and irregular cycles, hormonal and copper IUDs, the pill, coming off the pill, PCOS, PMDD, perimenopause, trying to conceive and early postpartum. Self-reported results: 89% better digestion and regularity, 78% fewer PMS symptoms (less cramping, mood swings and fatigue), 71% more energy, 67% better sleep (reported by participants with PMDD and PCOS), 64% more cycle awareness and 44% better mood and mental clarity. Many noted mild stomach upset in the first few days that resolved quickly. All 45 said they were open to continued use. GoodCycle notes these are self-reported results, individual results may vary, and the statements have not been evaluated by the FDA.', 'GoodCycle''s 2024 consumer focus group: 45 people used the routine for a full cycle and self-reported results, with no comparison group. 89% reported better digestion and regularity, 78% fewer PMS symptoms, 71% more energy, 67% better sleep, 64% more cycle awareness and 44% better mood. GoodCycle notes results are self-reported and individual results may vary. Customer quotes on takegoodcycle.com describe easier cramps, steadier energy and support coming off birth control.', 'No clinical trial of DailyBasis itself is cited by GoodCycle; its evidence is a 45-person self-reported focus group and published research on individual ingredients.', 'brand', 'Sourced from GoodCycle''s own materials (takegoodcycle.com, its sell sheet and its 2024 consumer study summary), not independent clinical literature.', 'curated', false, false, null, true, '{"faqUrl":"https://takegoodcycle.com/pages/faq","discountCode":{"code":"AYNAHEALTH","percentOff":30,"live":false,"note":"Pending GoodCycle testing after the rebrand (2026-10-27)."},"gallery":["/products/goodcycle/daily-basis-both.webp","/products/goodcycle/daily-basis-replenish.webp","/products/goodcycle/daily-basis-balance.webp","/products/goodcycle/daily-basis-replenish-facts.webp","/products/goodcycle/daily-basis-balance-facts.webp"],"doctorOpinionShort":"Formulated by an OB/GYN, per GoodCycle. Replenish is built for the first half of the cycle and Balance for the second half, as the brand describes them.","doctorOpinionCitations":[{"url":"https://takegoodcycle.com/pages/ingredients","label":"takegoodcycle.com: Ingredients (who formulated it, and why each ingredient)"},{"url":"https://takegoodcycle.com/pages/science","label":"takegoodcycle.com: Science"}],"whoItsFor":["Adults who menstruate and want one daily routine timed to the two halves of the cycle (per GoodCycle)","Irregular, shorter or longer cycles: GoodCycle says to match each formula to where you are in your own cycle","On hormonal birth control: GoodCycle says it can be used, and to check with a doctor if you don''t get a period, since it contains iron"],"howToUse":{"intro":"Per GoodCycle''s directions:","steps":["Mix one stick pack into 8 to 10 oz of cold water or another cold drink. Take it with food if you''re new to supplements.","Replenish: start on the first day of your period and take it daily through ovulation, about 14 days.","Balance: switch at ovulation and take it daily until your next period starts, about 14 days.","When your next period begins, go back to Replenish. You can start at any point in your cycle with the matching formula.","Take one stick pack a day, not more, unless a clinician tells you otherwise."],"sourceUrl":"https://takegoodcycle.com/pages/faq","sourceLabel":"takegoodcycle.com: FAQ"},"warnings":["Pregnant, postpartum or breastfeeding: GoodCycle says it isn''t formulated for pregnancy and to ask your clinician before starting.","Trying to conceive: GoodCycle says not to take it in addition to a prenatal vitamin without a doctor''s direction, to avoid too much of any nutrient.","Taking prescription medicines, or have PCOS, endometriosis, PMDD or another diagnosed condition: talk with your clinician first (GoodCycle and the FDA both advise this).","Not menstruating or menopausal: GoodCycle says it may not be the right fit, and to check with a clinician because it contains iron.","Teens: GoodCycle says it is formulated for adults and to ask a pediatrician first."],"ingredients":"Vitamins A, C, D3, E, K2 and B vitamins (incl. P-5-P B6, 5-MTHF folate, methyl B12), calcium, iron, iodine, magnesium, zinc, selenium, manganese, chromium, molybdenum, CoQ10, greens blend, botanicals (broccoli, green tea extract, lutein in Replenish; quercetin, alpha lipoic acid, phosphatidylcholine in Balance), amino acids (NAC, taurine, BCAAs), probiotics.","ingredientScienceNote":"A few of the ingredients GoodCycle highlights, with what published research says about each ingredient. These studies tested the ingredient on its own, often at a different dose, not DailyBasis.","ingredientScience":[{"name":"Vitamin B6 and magnesium","text":"A systematic review of nine trials (940 women) found vitamin B6 at doses up to 100 mg a day likely helps premenstrual symptoms, though most of the trials were low quality. In a small trial, magnesium plus B6 lowered PMS scores the most of three groups, but scores also fell with placebo. Balance has 20 mg of B6 and 150 mg of magnesium per serving, lower than many of the doses studied.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10334745/","label":"PubMed (NIH): Vitamin B-6 for premenstrual syndrome, systematic review (BMJ, 1999)"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3208934/","label":"NIH (PMC): Magnesium, and magnesium plus vitamin B6, on PMS severity (Iran J Nurs Midwifery Res, 2010)"}]},{"name":"Calcium","text":"In a double-blind trial of 66 students with PMS, 500 mg of calcium a day for two months reduced PMS symptom scores, including mood symptoms, compared with placebo. Balance has 310 mg of calcium per serving.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28217679/","label":"PubMed (NIH): Calcium for premenstrual syndrome, double-blind randomized trial (Obstet Gynecol Sci, 2017)"}]},{"name":"Iron","text":"Monthly blood loss raises iron needs. In a 16-week study of teen girls in Indonesia, iron tablets improved iron levels compared with placebo whether taken weekly or for four days during the period, but weekly dosing raised hemoglobin more. Replenish has 18 mg of iron and Balance 12.3 mg, so DailyBasis provides iron every day of the cycle.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/11890637/","label":"PubMed (NIH): Iron during menstruation vs. weekly iron supplementation (Asia Pac J Clin Nutr, 2002)"}]}],"scientificCitations":[],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"platform":"website","url":"https://www.fda.gov/food/information-consumers-using-dietary-supplements/questions-and-answers-dietary-supplements","text":"FDA: Questions and answers on dietary supplements","summary":"The FDA does not have the authority to approve dietary supplements before they are marketed, and advises talking with a clinician before using one.","justification":"Conservative ayna classification: category or adjacent evidence only; this source does not validate this specific product."}]},"community":{"links":[{"platform":"website","url":"https://takegoodcycle.com/products/daily-basis","text":"takegoodcycle.com: DailyBasis","summary":"GoodCycle''s product page, with customer quotes and directions."},{"platform":"website","url":"https://takegoodcycle.com/pages/faq","text":"takegoodcycle.com: FAQ","summary":"GoodCycle''s answers on cycle timing, birth control, pregnancy, allergens and medicines."},{"platform":"website","url":"https://takegoodcycle.com/pages/references","text":"takegoodcycle.com: Scientific references","summary":"The research list GoodCycle cites for its ingredients."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
